from dataclasses import dataclass
from typing import Optional

@dataclass
class User:
    id: int
    name: str
    email: Optional[str]

def find(users: list[User], uid: int) -> Optional[User]:
    for u in users:
        if u.id == uid:
            return u
    return None

def total_age(ages: list[int]) -> int:
    return sum(ages)

