    users = [User(1, "a", None), User(id=2, name="b", email=None)]
    u = find(users, 1)
    assert u is not None
    print(u.name)
    print(users[0].name)
    x: int = total_age([1, 2])
    undefined_var = "placeholder"
    print(undefined_var)
    y: int = total_age([1])
    print((users[0].email or "").upper())

